import pg from 'pg';
import {PostgresExtensionApprovals} from '../../dist/index.js';
const schema=process.env.APP_MIXER_TEST_SCHEMA,phase=process.env.APP_MIXER_TEST_PHASE,pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${schema}`}),scope={tenantId:'tenant',applicationId:'demo'},actor={tenantId:'tenant',principalId:'worker'},reference={id:'example.report',version:'1.0.0',scope:'application'},operation={extensionId:'example.report',kind:'tool',name:'lookup'};
try{const client=await pool.connect();try{const store=new PostgresExtensionApprovals({clock:()=>100,authorize:()=>true,query:async(sql,args)=>{if(!sql.startsWith('WITH changed AS'))return client.query(sql,args);await client.query('BEGIN');const result=await client.query(sql,args);if(phase==='before-commit'){process.send?.(phase);await new Promise(()=>{});}await client.query('COMMIT');process.send?.(phase);await new Promise(()=>{});return result;}});await store.decide(actor,scope,reference,operation,{allowed:true,expiresAt:500,expectedRevision:0});throw Error('Expected process termination');}finally{client.release();}}catch(error){process.send?.({error:String(error)});process.exitCode=1;}finally{await pool.end();}
